from pathlib import Path
import subprocess,json,hashlib,random,statistics,fcntl
b=Path(__file__).resolve().parent;variants=['baseline','control','unroll3'];work=[]
for n in [0,1,2,3,4,7,8,15,16,31,32,33,1024,100000,1000000]:
 for shuffled in ([0,1]if n>=100000 else[0]):work.append((n,100000 if n<=32 else 10000 if n<=1024 else 10 if n==100000 else 2,shuffled))
d={'cpu':18,'builds':json.loads((b/'build-results.json').read_text()),'rows':[],'summary':{},'workloads':work,'samples':7,'variants':variants,'flags':'C++23 -O2; checked and SKIP tested; atomic_signal_fence before every chain_size call'}
assert json.loads((b/'check-results.json').read_text()).get('passed')
with open('/tmp/sirkit_node_count18.lock','w')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for cc in ['gcc','clang']:
  for skip in [False,True]:
   ws=work if skip else[(32,100000,0),(100000,10,0),(100000,10,1)]
   for i,(n,reps,shuffled)in enumerate(ws):
    for rep in range(d['samples']):
     vs=variants.copy();random.Random(i*41+rep).shuffle(vs);sums=set()
     for v in vs:
      q=subprocess.check_output(['taskset','-c','18',str(b/f'{cc}-{skip}-{v}'),str(n),str(reps),str(shuffled)],text=True).split();sums.add(q[1]);d['rows'].append({'compiler':cc,'skip':skip,'variant':v,'n':n,'shuffled':shuffled,'reps':reps,'round':rep,'ns':float(q[0]),'checksum':q[1]})
     assert len(sums)==1
  ss={}
  for x in d['rows']:
   if x['compiler']!=cc:continue
   key=f"{'skip'if x['skip']else'checked'}_{x['n']}_{x['shuffled']}"
   if key in ss:continue
   med={v:statistics.median(y['ns']for y in d['rows']if y['compiler']==cc and y['skip']==x['skip']and y['variant']==v and y['n']==x['n']and y['shuffled']==x['shuffled'])for v in variants};ss[key]={'median_ns':med,'ratios':{v:t/med['baseline']for v,t in med.items()}}
  d['summary'][cc]=ss;(b/'results.json').write_text(json.dumps(d,indent=2)+'\n');print('measured',cc,flush=True)

