  else:
   cmd=['taskset','-c','22',*compiler,'-std=c++23','-O2',str(b/('main-'+v+'.cpp')),'-o',str(exe)];p=subprocess.run(cmd,capture_output=True);assert not p.returncode and not p.stderr,p.stderr.decode()
  d['build'].append({'compiler':cc,'variant':v,'command':cmd,'sha256':hashlib.sha256(exe.read_bytes()).hexdigest()})
 print('compiled main',cc,flush=True)
import time
